    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter()]
        [int] $DestPort,

        [Parameter()]
        [ValidateSet('ETHERNETwithDOT1Q', 'ETHERNET', 'IP')]
        [string] $Grepayload,

        [Parameter()]
        [string] $IpsecProfileName,

        [Parameter(Mandatory)]
        [string] $Local,

        [Parameter(Mandatory, Position = 0)]
        [string] $Name,

        [Parameter()]
        [string] $OwnerGroup,

        [Parameter()]
        [ValidateSet('IPIP', 'GRE', 'IPSEC', 'UDP', 'GENEVE')]
        [string] $Protocol,

        [Parameter(Mandatory)]
        [string] $Remote,

        [Parameter(Mandatory)]
        [string] $RemotesubnetMask,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [string] $Tosinherit,

        [Parameter()]
        [int] $Vlan,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [string] $Vlantagging,

        [Parameter()]
