        [Parameter()]
        [switch] $Natprefix,

        [Parameter()]
        [switch] $Ndbasereachtime,

        [Parameter()]
        [switch] $Ndretransmissiontime,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $RaLearning,

